const COMPOSITE_FS = `#version 300 es
precision highp float;
uniform sampler2D uField;
uniform sampler2D uSky;
uniform vec2 uRes;
uniform vec2 uFieldPx;
uniform float uTime;
uniform float uAspect;
uniform vec3 uObstacle;     // uv x, uv y, uv radius (y units)
